package dev.zomboid.turretpower;
import java.util.*;import java.util.function.Consumer;import net.minecraft.world.item.*;import net.neoforged.neoforge.registries.RegisterEvent;import dev.zomboid.hordes.WorldTuning;import com.entropy.tacz_turrets.turret.TurretEntity;
public class ScrapChecks {
 static int checks;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 public static class Random{public double value;public int index,calls;public double nextDouble(){calls++;return value;}public int nextInt(int n){return index%n;}}
 public static class World extends Checks.W{public Random random=new Random();public Random getRandom(){return random;}}
 public static class Inventory{public Object[] items;public int changed;public Inventory(int n){items=new Object[n];}public int getContainerSize(){return items.length;}public Object getItem(int i){return items[i];}public void setItem(int i,Object stack){if(items[i]!=null)throw new AssertionError("owned slot overwritten");items[i]=stack;}public void setChanged(){changed++;}}
 public static class Barrel extends Inventory{public Barrel(int n){super(n);}}public static class Chest extends Inventory{public Chest(int n){super(n);}}
 public static class Body{public Inventory inventory;public Body(Inventory i){inventory=i;}}
 public record Params(World level){public World getLevel(){return level;}}
 public static class Creative{public Object tab;public List<Object> items=new ArrayList<>();public Object getTabKey(){return tab;}public void accept(Object item){items.add(item);}}
 static int count(Inventory inv){int n=0;for(Object s:inv.items)if(s!=null)n++;return n;}
 static long heard(World w,String name){return w.sounds.stream().filter(s->s.toString().contains(name)).count();}
 public static void main(String[]args){Object listener=R.make("dev.zomboid.turretpower.RegistryListener2");ok(listener instanceof Consumer<?>,"real typed listener implements Consumer");ok(listener.getClass().getGenericInterfaces()[0].getTypeName().contains("RegisterEvent"),"event type retained for bus inference");RegisterEvent items=new RegisterEvent(net.minecraft.core.registries.Registries.ITEM);((Consumer<Object>)listener).accept(items);ok(items.registered.size()==1&&Scrap.ITEM!=null,"scrap registered by native listener");ok(((Item)Scrap.ITEM).props.max==64,"stack size 64");RegisterEvent sounds=new RegisterEvent(net.minecraft.core.registries.Registries.SOUND_EVENT);((Consumer<Object>)listener).accept(sounds);ok(sounds.registered.size()==3&&Sounds.SOUNDS.size()==3,"idle movement and target sounds registered");
  Creative creative=new Creative();creative.tab=com.tacz.guns.init.ModCreativeTabs.OTHER_TAB.getKey();Scrap.creative(creative);ok(creative.items.size()==1&&creative.items.get(0)==Scrap.ITEM,"creative tab item");creative.tab=new Object();Scrap.creative(creative);ok(creative.items.size()==1,"other creative tab untouched");
  World w=new World();ItemStack owned=new ItemStack(new Item(new Item.Properties()),1);Inventory inv=new Inventory(9);inv.items[0]=owned;w.random.index=4;w.random.value=.149;ScrapLoot.corpse(new Body(inv),w,null);ok(count(inv)==2&&inv.items[0]==owned&&inv.changed==1,"corpse adds one without replacing gear");ok(((ItemStack)inv.items[5]).item==Scrap.ITEM&&((ItemStack)inv.items[5]).count==1,"corpse randomized empty slot and one scrap");
  Inventory miss=new Inventory(9);w.random.value=.15;ScrapLoot.corpse(new Body(miss),w,null);ok(count(miss)==0,"corpse probability upper boundary");Inventory full=new Inventory(1);full.items[0]=owned;w.random.value=0;ScrapLoot.corpse(new Body(full),w,null);ok(full.items[0]==owned&&full.changed==0,"full corpse retains owned gear");
  Inventory scaled=new Inventory(9);WorldTuning.data.put("cadaveres_cantidad",.2);w.random.value=.031;ScrapLoot.corpse(new Body(scaled),w,null);ok(count(scaled)==0,"desolate scarcity scales electronic drop");w.random.value=.029;ScrapLoot.corpse(new Body(scaled),w,null);ok(count(scaled)==1,"desolate nonzero drop retained");WorldTuning.data.clear();
  WorldTuning.data.put("cadaveres_materiales",0.0);Inventory disabled=new Inventory(9);w.random.value=0;ScrapLoot.corpse(new Body(disabled),w,null);ok(count(disabled)==0,"corpse materials disabled honored");WorldTuning.data.clear();
  ArrayList<Object> loot=new ArrayList<>();Barrel barrel=new Barrel(9);w.random.value=.2;Object result=ScrapLoot.container(loot,barrel,new Params(w));ok(result==loot&&loot.size()==1&&((ItemStack)loot.get(0)).count==2,"barrel adds one stack of two scrap");loot.clear();w.random.value=.27;ScrapLoot.container(loot,barrel,new Params(w));ok(loot.size()==1&&((ItemStack)loot.get(0)).count==1,"barrel one-scrap branch");loot.clear();w.random.value=.3;ScrapLoot.container(loot,barrel,new Params(w));ok(loot.isEmpty(),"barrel probability boundary");w.random.value=0;ScrapLoot.container(loot,new Chest(9),new Params(w));ok(loot.isEmpty(),"chests not changed by barrel-specific drop");
  Barrel packed=new Barrel(1);packed.items[0]=owned;ScrapLoot.container(loot,packed,new Params(w));ok(loot.isEmpty()&&packed.items[0]==owned,"full barrel untouched");loot.add(owned);ScrapLoot.container(loot,new Barrel(1),new Params(w));ok(loot.size()==1,"existing generated loot not displaced");loot.clear();WorldTuning.data.put("cofres_cantidad",0.0);ScrapLoot.container(loot,barrel,new Params(w));ok(loot.isEmpty(),"container quantity disabled honored");WorldTuning.data.clear();
  Object item=Scrap.ITEM;Scrap.ITEM=null;ScrapLoot.container(loot,barrel,new Params(w));ScrapLoot.corpse(new Body(new Inventory(9)),w,null);ok(loot.isEmpty(),"item unavailable creates no invalid stacks");Scrap.ITEM=item;w.client=true;ScrapLoot.container(loot,barrel,new Params(w));ok(loot.isEmpty(),"client generates no loot");w.client=false;
  // The actual patched Remains bridge executes native balance first and adds scrap after it.
  inv=new Inventory(9);inv.items[0]=owned;w.random.value=0;dev.zomboid.remains.CorpseBridge35.body(new Body(inv),w,null);ok(dev.zomboid.hordes.CorpseBalance35.calls==1&&count(inv)==2&&inv.items[0]==owned,"native Remains bridge retains original body and adds scrap");
  loot.clear();Object nativeResult=R.call(R.type("dev.zomboid.hordes.LootProfiles"),"container",loot,barrel,new Params(w));ok(dev.zomboid.hordes.SimpleLoot.calls==1&&nativeResult==loot&&loot.size()==1,"native container wrapper executes generation then scrap hook");
  // Power/LOS/range behavior remains in the exact Link class from .1.
  TurretEntity t=new TurretEntity(w);t.target=new Checks.T(w);Checks.P gp=new Checks.P(0,0,0);dev.zomboid.survival.MachineEntity g=new dev.zomboid.survival.MachineEntity();w.machines.put(gp,g);w.blocks.put(gp,new Checks.S("doomsday_decoration:generator"));dev.zomboid.survival.MachineEntity.GENERATORS.put(w,Set.of(gp));w.time=0;Sounds.tick(t);ok(heard(w,"servo_idle")==1&&heard(w,"target_alert")==1,"powered idle and recognized target audible");
  w.time=1;t.yaw=12;Sounds.tick(t);ok(heard(w,"servo_move")==1,"actual head yaw emits servo");w.time=2;t.yaw=24;Sounds.tick(t);ok(heard(w,"servo_move")==1,"servo rate limited");w.time=9;t.pitch=15;Sounds.tick(t);ok(heard(w,"servo_move")==2,"actual pitch emits servo");w.time=10;Sounds.tick(t);ok(heard(w,"servo_move")==2,"stationary turret no movement sound");
  w.time=11;t.target=new Checks.T(w);Sounds.tick(t);ok(heard(w,"target_alert")==1,"recognition rate limited");w.time=60;Sounds.tick(t);ok(heard(w,"target_alert")==2,"pending recognized target announced after cooldown");t.visible=false;w.time=120;t.target=new Checks.T(w);Sounds.tick(t);ok(heard(w,"target_alert")==2,"wall prevents target recognition");t.visible=true;Sounds.tick(t);ok(heard(w,"target_alert")==3,"visible target recognized");
  int total=w.sounds.size();g.energy.stored=0;w.time=200;t.yaw=90;Sounds.tick(t);ok(w.sounds.size()==total,"no motor or alerts without power");g.energy.stored=10000;w.client=true;Sounds.tick(t);ok(w.sounds.size()==total,"client does not duplicate network sounds");w.client=false;ok(Sounds.angle(359-1)==2&&Sounds.angle(-359+1)==2,"yaw wrap avoids false full turn");
  System.out.println("Scrap, native loot bridges, registry and movement sound checks: "+checks);
 }
}
